ALTER TABLE "run_plans" DROP CONSTRAINT "plan_metadata_valid";--> statement-breakpoint
ALTER TABLE "run_plans" ADD CONSTRAINT "plan_metadata_valid" CHECK ("run_plans"."attempt_version">0 AND "run_plans"."message_role"='USER' AND "run_plans"."version" IN ('planner-v1','planner-v2','planner-v3') AND "run_plans"."original_hash" ~ '^[a-f0-9]{64}$' AND jsonb_typeof("run_plans"."plan")='object' AND "run_plans"."plan"->>'action' IN ('ANSWER','CLARIFY') AND jsonb_typeof("run_plans"."context_ids")='array' AND jsonb_array_length("run_plans"."context_ids")<=6);